draw:
var P = p.power * 1000, m = p.mass, c = p.drag;
var vTop = Math.sqrt(P / c);
var tau = m / (2 * c);
var Tmax = tau * Math.log(50.0);
var padL = 44, padB = 30, padT = 16, padR = 14;
var plotW = W - padL - padR, plotH = H - padT - padB;
var X = function (s) { return padL + plotW * (s / Tmax); };
var Y = function (v) { return padT + plotH * (1 - v / (vTop * 1.12)); };

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;

// axes
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(padL, padT); ctx.lineTo(padL, padT + plotH); ctx.lineTo(padL + plotW, padT + plotH);
ctx.stroke();

// top-speed asymptote
ctx.strokeStyle = C.faint;
ctx.setLineDash([4, 4]);
ctx.beginPath(); ctx.moveTo(padL, Y(vTop)); ctx.lineTo(padL + plotW, Y(vTop)); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.faint;
ctx.fillText("top speed " + vTop.toFixed(1) + " m/s", padL + 6, Y(vTop) - 5);

// the drag-free sqrt curve, for comparison
ctx.strokeStyle = C.rule;
ctx.setLineDash([2, 4]);
ctx.beginPath();
for (var i = 0; i <= 120; i++) {
  var s = Tmax * i / 120;
  var vf = Math.sqrt(2 * P * s / m);
  if (vf > vTop * 1.12) break;
  i === 0 ? ctx.moveTo(X(s), Y(vf)) : ctx.lineTo(X(s), Y(vf));
}
ctx.stroke();
ctx.setLineDash([]);

// real curve with drag
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.beginPath();
for (var j = 0; j <= 160; j++) {
  var s2 = Tmax * j / 160;
  var v2 = vTop * Math.sqrt(1 - Math.exp(-s2 / tau));
  j === 0 ? ctx.moveTo(X(s2), Y(v2)) : ctx.lineTo(X(s2), Y(v2));
}
ctx.stroke();
ctx.lineWidth = 1;

// moving marker
var cyc = Tmax * 1.25;
var now = Math.min(t % cyc, Tmax);
var vNow = vTop * Math.sqrt(1 - Math.exp(-now / tau));
ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(X(now), padT + plotH); ctx.lineTo(X(now), Y(vNow)); ctx.stroke();
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(X(now), Y(vNow), 5, 0, Math.PI * 2); ctx.fill();

// force arrow: length proportional to net force P/v - c v
var Fnet = vNow > 0.2 ? (P / vNow - c * vNow) : 0;
var Fmax = P / (vTop * 0.08);
var arrow = (plotW * 0.18) * Math.min(1, Fnet / Fmax);
ctx.strokeStyle = C.accent;
ctx.beginPath();
ctx.moveTo(X(now), Y(vNow));
ctx.lineTo(X(now) + arrow, Y(vNow));
ctx.stroke();

// labels
ctx.fillStyle = C.ink;
ctx.fillText("v (m/s)", 4, padT + 10);
ctx.fillText("t (s)", padL + plotW - 26, padT + plotH + 20);
ctx.fillStyle = C.faint;
ctx.fillText("0", padL - 8, padT + plotH + 16);
ctx.fillText(Tmax.toFixed(0), padL + plotW - 10, padT + plotH + 16);
ctx.fillStyle = C.rule;
ctx.fillText("no drag: v = sqrt(2Pt/m)", padL + 6, padT + 12);

out.note = "t = " + now.toFixed(1) + " s, v = " + vNow.toFixed(1) + " m/s ("
  + (100 * vNow / vTop).toFixed(0) + "% of top), driving force P/v = "
  + (vNow > 0.2 ? (P / vNow).toFixed(0) : "huge") + " N";

var th = p.angle * Math.PI / 180;
var v = p.speed, m = p.mass, D = p.drag;
var g = 9.8;
var Fgrav = m * g * Math.sin(th);
var Fdrive = Fgrav + D;
var Pw = Fdrive * v;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.5;

var baseY = H - 26, baseX = 22;
var run = W - 90;
var rise = run * Math.tan(th);
if (rise > H - 70) { run = (H - 70) / Math.tan(th); rise = H - 70; }

// the incline
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(baseX, baseY);
ctx.lineTo(baseX + run, baseY);
ctx.lineTo(baseX + run, baseY - rise);
ctx.closePath();
ctx.stroke();

// angle label
ctx.fillStyle = C.ink;
ctx.fillText(p.angle.toFixed(0) + " deg", baseX + 16, baseY - 6);

// car sits partway up the slope
var f = 0.55;
var cx = baseX + run * f, cy = baseY - rise * f;
var ux = Math.cos(th), uy = -Math.sin(th);
ctx.fillStyle = C.figure;
ctx.save();
ctx.translate(cx, cy);
ctx.rotate(-th);
ctx.fillRect(-16, -13, 32, 11);
ctx.restore();

function arrow(x0, y0, dx, dy, col, label, lx, ly) {
  ctx.strokeStyle = col;
  ctx.fillStyle = col;
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x0 + dx, y0 + dy); ctx.stroke();
  var L = Math.sqrt(dx * dx + dy * dy);
  if (L > 1) {
    var hx = dx / L, hy = dy / L;
    ctx.beginPath();
    ctx.moveTo(x0 + dx, y0 + dy);
    ctx.lineTo(x0 + dx - 7 * hx + 4 * hy, y0 + dy - 7 * hy - 4 * hx);
    ctx.lineTo(x0 + dx - 7 * hx - 4 * hy, y0 + dy - 7 * hy + 4 * hx);
    ctx.closePath(); ctx.fill();
  }
  ctx.fillText(label, x0 + dx + lx, y0 + dy + ly);
}

var scale = 52 / Math.max(Fdrive, 1);
var ax = cx + ux * 16, ay = cy - 14 + uy * 16;

arrow(ax, ay, ux * Fdrive * scale, uy * Fdrive * scale, C.accent, "F drive", 4, -4);
arrow(cx - ux * 16, cy - 14 - uy * 16, -ux * D * scale, -uy * D * scale, C.figure, "drag", -34, 14);
arrow(cx, cy - 8, 0, m * g * Math.sin(th) * scale * 0.6, C.ink, "", 0, 0);
ctx.fillStyle = C.ink;
ctx.fillText("mg", cx + 5, cy - 8 + m * g * Math.sin(th) * scale * 0.6);

// velocity arrow above the car
arrow(cx - ux * 10, cy - 30 - uy * 10, ux * 42, uy * 42, C.faint, "v = " + v.toFixed(0) + " m/s", -20, -8);

ctx.fillStyle = C.ink;
ctx.fillText("P = F drive x v", 10, 16);
ctx.fillStyle = C.faint;
ctx.fillText("F drive = mg sin(angle) + drag  (steady speed)", 10, 32);

out.note = "mg sin = " + Fgrav.toFixed(0) + " N, drag = " + D.toFixed(0)
  + " N, so F = " + Fdrive.toFixed(0) + " N and P = " + (Pw / 1000).toFixed(1) + " kW";

var b = p.b, vSel = p.v;
var vMax = 30;
var padL = 46, padB = 30, padT = 16, padR = 14;
var plotW = W - padL - padR, plotH = H - padT - padB;
var Pmax = b * Math.pow(vMax, 3);
var X = function (v) { return padL + plotW * (v / vMax); };
var Y = function (P) { return padT + plotH * (1 - P / Pmax); };

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(padL, padT); ctx.lineTo(padL, padT + plotH); ctx.lineTo(padL + plotW, padT + plotH);
ctx.stroke();

// cubic curve
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.beginPath();
for (var i = 0; i <= 140; i++) {
  var v = vMax * i / 140;
  i === 0 ? ctx.moveTo(X(v), Y(0)) : ctx.lineTo(X(v), Y(b * v * v * v));
}
ctx.stroke();
ctx.lineWidth = 1;

// selected speed and double it
var P1 = b * vSel * vSel * vSel;
var v2 = Math.min(2 * vSel, vMax);
var P2 = b * v2 * v2 * v2;

ctx.strokeStyle = C.faint;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(X(vSel), padT + plotH); ctx.lineTo(X(vSel), Y(P1)); ctx.lineTo(padL, Y(P1)); ctx.stroke();
ctx.beginPath(); ctx.moveTo(X(v2), padT + plotH); ctx.lineTo(X(v2), Y(P2)); ctx.lineTo(padL, Y(P2)); ctx.stroke();
ctx.setLineDash([]);

ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(X(vSel), Y(P1), 5, 0, Math.PI * 2); ctx.fill();
ctx.beginPath(); ctx.arc(X(v2), Y(P2), 5, 0, Math.PI * 2); ctx.fill();

ctx.fillStyle = C.ink;
ctx.fillText("P (kW)", 4, padT + 10);
ctx.fillText("v (m/s)", padL + plotW - 34, padT + plotH + 20);
ctx.fillText("P = b v^3", padL + plotW - 70, padT + 24);
ctx.fillStyle = C.faint;
ctx.fillText("0", padL - 8, padT + plotH + 16);
ctx.fillText(vMax.toFixed(0), padL + plotW - 6, padT + plotH + 16);
ctx.fillText((Pmax / 1000).toFixed(0), 6, padT + plotH - 2);
ctx.fillStyle = C.accent;
ctx.fillText("v", X(vSel) - 3, padT + plotH + 16);
ctx.fillText("2v", X(v2) - 6, padT + plotH + 16);

out.note = "at " + vSel.toFixed(1) + " m/s need " + (P1 / 1000).toFixed(2)
  + " kW; at " + v2.toFixed(1) + " m/s need " + (P2 / 1000).toFixed(2)
  + " kW, a factor of " + (P1 > 0 ? (P2 / P1).toFixed(2) : "-");

var rate = p.rate, v = p.speed;
var F = rate * v;
var Pmotor = rate * v * v;
var Pke = 0.5 * rate * v * v;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.5;

var beltY = H * 0.62;
var x0 = W * 0.12, x1 = W * 0.88;
var r = 13;

// belt loop
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(x0, beltY - r); ctx.lineTo(x1, beltY - r); ctx.stroke();
ctx.beginPath(); ctx.moveTo(x0, beltY + r); ctx.lineTo(x1, beltY + r); ctx.stroke();
ctx.beginPath(); ctx.arc(x0, beltY, r, Math.PI / 2, 3 * Math.PI / 2); ctx.stroke();
ctx.beginPath(); ctx.arc(x1, beltY, r, -Math.PI / 2, Math.PI / 2); ctx.stroke();

// grain falling from a hopper, animated
var dropX = W * 0.34;
ctx.strokeStyle = C.faint;
ctx.beginPath();
ctx.moveTo(dropX - 22, 8); ctx.lineTo(dropX - 7, 40);
ctx.lineTo(dropX + 7, 40); ctx.lineTo(dropX + 22, 8);
ctx.stroke();
ctx.fillStyle = C.figure;
for (var k = 0; k < 6; k++) {
  var ph = ((t * 1.4 + k / 6) % 1);
  var gy = 40 + ph * (beltY - r - 40);
  var gx = dropX + ((k % 3) - 1) * 4;
  ctx.beginPath(); ctx.arc(gx, gy, 3, 0, Math.PI * 2); ctx.fill();
}

// grain already on the belt, carried right
for (var q = 0; q < 7; q++) {
  var xg = dropX + ((t * v * 9 + q * 26) % (x1 - dropX - 6));
  ctx.beginPath(); ctx.arc(xg, beltY - r - 3, 3, 0, Math.PI * 2); ctx.fill();
}

function arr(x0a, y0a, dx, dy, col) {
  ctx.strokeStyle = col; ctx.fillStyle = col;
  ctx.beginPath(); ctx.moveTo(x0a, y0a); ctx.lineTo(x0a + dx, y0a + dy); ctx.stroke();
  var L = Math.sqrt(dx * dx + dy * dy);
  var hx = dx / L, hy = dy / L;
  ctx.beginPath();
  ctx.moveTo(x0a + dx, y0a + dy);
  ctx.lineTo(x0a + dx - 7 * hx + 4 * hy, y0a + dy - 7 * hy - 4 * hx);
  ctx.lineTo(x0a + dx - 7 * hx - 4 * hy, y0a + dy - 7 * hy + 4 * hx);
  ctx.closePath(); ctx.fill();
}

// belt velocity and motor force
arr(x1 - 90, beltY + r + 22, 60, 0, C.faint);
ctx.fillStyle = C.faint;
ctx.fillText("belt v = " + v.toFixed(1) + " m/s", x1 - 150, beltY + r + 26);

arr(dropX + 10, beltY - r - 14, 52, 0, C.accent);
ctx.fillStyle = C.accent;
ctx.fillText("F = (dm/dt) v = " + F.toFixed(1) + " N", dropX + 16, beltY - r - 22);

ctx.fillStyle = C.ink;
ctx.fillText("grain in at " + rate.toFixed(1) + " kg/s", dropX - 40, 54);
ctx.fillText("motor P = (dm/dt) v^2", 10, H - 22);
ctx.fillStyle = C.faint;
ctx.fillText("half becomes kinetic energy, half is rubbed away as heat", 10, H - 6);

out.note = "motor supplies " + Pmotor.toFixed(1) + " W; grain gains KE at "
  + Pke.toFixed(1) + " W; friction wastes " + (Pmotor - Pke).toFixed(1) + " W";
